button:hover { background: red; }
input:focus { border-color: blue; }

.text-box::before {
  content: "★"; /* Bắt buộc phải có thuộc tính content */
  color: yellow;
  display: inline-block;
}

:root { --main-bg: rgba(0, 0, 0, 0.5); }
.box {
  width: 50%; /* Bằng nửa thẻ cha */
  font-size: 2rem; /* Bằng 2 lần kích thước font gốc */
  background-color: var(--main-bg);
}

.parent { position: relative; }
.child {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 10; /* Lớp ưu tiên trục Z, số to nổi lên trên */
}
.header { position: sticky; top: 0; }

.hero {
  background-image: url('./bg.png');
  background-size: cover;
  background-position: center bottom;
  background-repeat: no-repeat;
  /* Shorthand gộp */
  background: #333 url('./bg.png') no-repeat center/cover;
}

.box {
  border: 1px solid red;
  border-bottom: 2px dashed #000;
  border-radius: 5px; /* Bo góc */
  box-sizing: border-box; 
}

.box {
  margin-bottom: 20px;
  /* Căn giữa phần tử block theo chiều ngang */
  margin: 0 auto;
}

.box {
  padding-top: 10px;
  padding-right: 20px;
  /* Shorthand: Top Right Bottom Left */
  padding: 10px 20px 15px 5px;
  /* Shorthand: Vertical Horizontal */
  padding: 10px 20px;
}

/* Cú pháp: Selector { Property: Value; } */
* { margin: 0; padding: 0; } /* Reset CSS toàn cục */
#header .nav-item { font-weight: bold; }

a:hover { color: blue; }

.title::after {
  content: "";
  display: block;
  width: 100%;
  height: 2px;
  background: red;
}

.parent { position: relative; }
.child { 
  position: absolute; 
  top: 50%; 
  left: 50%; 
  transform: translate(-50%, -50%); 
}

.hero {
  background: #000 url('bg.jpg') no-repeat center center / cover;
}

.box {
  width: 200px;
  padding: 20px;
  border: 2px solid black;
  box-sizing: border-box;
}

:root {
  --primary-color: #3498db;
}

.text {
  color: var(--primary-color);
  font-size: 1.5rem; /* = 24px nếu root font-size là 16px */
}

/* Bắt thẻ p */
p { color: red; }

/* Bắt class .box */
.box { width: 100px; }

/* Bắt id #header */
#header { background: black; }

worker_processes auto;
events { worker_connections 1024; }
http {
  include /etc/nginx/conf.d/*.conf;
}

server {
  listen 80;
  server_name example.com;
  location / {
    proxy_pass http://127.0.0.1:3000;
    proxy_set_header Host $host;
  }
}

{
  "name": "my-app",
  "scripts": {
    "dev": "node index.js",
    "start": "node index.js"
  }
}
